#!/usr/bin/env python3
"""Enable Beads in a project generated by scaffold-agent-project."""

from __future__ import annotations

import argparse
import os
import runpy
import shutil
import subprocess
import sys
from pathlib import Path

FIELDS = {
    "AGENTS.md": ("TRACKER_NOTE",),
    ".agents/skills/application-delivery/SKILL.md": (
        "TRACKER_ROUTE",
        "TRACKER_BOUNDARY",
    ),
    ".agents/skills/application-delivery/references/workflow.md": (
        "WORKFLOW_TITLE",
        "TRACKER_STEPS",
    ),
}

# Issue tracker configuration
ISSUE_PATH = "docs/agents/issue-tracker.md"
ISSUE_DOC = """# Issue tracker

Beads is the durable tracker for this project. `AGENTS.md` governs permission
for commits, publishing, and remote synchronization.

- Inspect context: `bd prime`
- Create work: `bd create "<title>" -t task` (choose another issue type when appropriate)
- Read an issue: `bd show <id>`
- Add a blocking edge: `bd dep add <blocked-id> <blocker-id>`
- Find unblocked work: `bd ready`
- Claim work: `bd update <id> --claim`
- Close verified work: `bd close <id>`

`bd ready` proves only that blockers are cleared; readiness for implementation
also requires a sufficiently specified issue. The `application-delivery` skill
owns planning, validation, and completion gates.
"""
ROUTE_LINE = "- For tracker operations, read `docs/agents/issue-tracker.md`."


def inspect(target: Path) -> dict[Path, str]:
    scaffold_path = (
        Path(__file__).resolve().parents[2]
        / "scaffold-agent-project/scripts/scaffold.py"
    )
    values = runpy.run_path(str(scaffold_path))["template_values"]
    old, new = values("project", "none"), values("project", "beads")
    changes: dict[Path, str] = {}

    for relative, keys in FIELDS.items():
        path = target / relative
        if path.is_symlink() or not path.is_file():
            raise ValueError(f"Expected scaffold file missing or symlinked: {path}")
        content = path.read_text(encoding="utf-8")
        updated = content
        for key in keys:
            before, after = old[key], new[key]
            if updated.count(before) == 1 and after not in updated:
                updated = updated.replace(before, after, 1)
            elif updated.count(after) != 1 or before in updated:
                raise ValueError(
                    f"Tracker instruction needs manual review: {path} ({key})"
                )
        if relative == "AGENTS.md" and ROUTE_LINE not in updated:
            anchor = f"- {new['TRACKER_NOTE']}"
            if updated.count(anchor) != 1:
                raise ValueError(f"Cannot locate Beads tracker declaration: {path}")
            updated = updated.replace(anchor, anchor + "\n" + ROUTE_LINE, 1)
        if updated != content:
            changes[path] = updated

    # Issue tracker
    issue = target / ISSUE_PATH
    if issue.is_symlink() or (issue.exists() and not issue.is_file()):
        raise ValueError(f"Invalid tracker document path: {issue}")
    if issue.exists():
        if "Beads" not in issue.read_text(encoding="utf-8")[:300]:
            raise ValueError(f"Existing tracker document needs review: {issue}")
    else:
        changes[issue] = ISSUE_DOC
    for path in changes:
        if path.exists() and not os.access(path, os.W_OK):
            raise ValueError(f"Destination is not writable: {path}")
        current = path.parent
        while current != target:
            if current.is_symlink():
                raise ValueError(f"Refusing symlink path: {current}")
            current = current.parent
        parent = next(parent for parent in path.parents if parent.exists())
        if not os.access(parent, os.W_OK | os.X_OK):
            raise ValueError(f"Destination is not writable: {parent}")
    return changes


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--target", default=".", help="Scaffolded project root")
    parser.add_argument("--mode", choices=("local", "shared"), default="local")
    parser.add_argument("--dry-run", action="store_true")
    args = parser.parse_args()

    requested = Path(args.target).expanduser()
    if requested.is_symlink() or not requested.is_dir():
        parser.error("Target must be an existing non-symlink directory")
    target = requested.resolve()
    try:
        changes = inspect(target)
    except (OSError, ValueError) as error:
        print(f"Setup blocked before Beads initialization: {error}", file=sys.stderr)
        return 1

    beads_path = target / ".beads"
    if beads_path.is_symlink():
        print("Refusing symlinked .beads directory.", file=sys.stderr)
        return 1
    initialized = beads_path.exists()
    if args.mode == "shared" and not initialized:
        status = (
            subprocess.run(
                ["git", "status", "--porcelain"],
                cwd=target,
                capture_output=True,
                text=True,
                check=False,
            )
            if shutil.which("git")
            else None
        )
        if status is None or status.returncode or status.stdout:
            print("Shared mode requires a clean Git working tree.", file=sys.stderr)
            return 1

    print(
        "Beads already initialized."
        if initialized
        else f"Initialize Beads ({args.mode})."
    )

    # Print changes
    for path in changes:
        print(
            f"{'Create' if not path.exists() else 'Update'} {path.relative_to(target)}"
        )

    # Dry run exits here
    if args.dry_run:
        return 0
    if not shutil.which("bd"):
        print("The `bd` executable was not found.", file=sys.stderr)
        return 1
    try:
        if not initialized:
            cmd = [
                "bd",
                "init",
                "--skip-agents",
                "--skip-hooks",
                "--non-interactive",
                "--init-if-missing",
            ]
            if args.mode == "local":
                cmd.append("--stealth")
            subprocess.run(cmd, cwd=target, check=True)
        subprocess.run(
            ["bd", "prime"], cwd=target, check=True, stdout=subprocess.DEVNULL
        )

        # Create or update files
        for path, content in changes.items():
            path.parent.mkdir(parents=True, exist_ok=True)
            if path.exists():
                path.write_text(content, encoding="utf-8")
            else:
                with path.open("x", encoding="utf-8") as f:
                    f.write(content)
    except (OSError, subprocess.CalledProcessError) as error:
        print(
            f"Setup incomplete: {error}; inspect state before retrying.",
            file=sys.stderr,
        )
        return 1
    print("Beads ready; project tracker guidance updated.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
